function kpi(lb, val, d, good) {
  return '<div class="card kpi"><div class="k-lb">' + esc(lb) + '</div><div class="k-v">' + val + '</div>' +
    '<div class="k-d"><i class="dot ' + (good ? '' : 'idle') + '" style="width:6px;height:6px"></i>' + esc(d) + '</div></div>';
}
function kvLine(k, v) { return '<div class="kv"><span class="k">' + esc(k) + '</span><span class="v">' + esc(v) + '</span></div>'; }
function lastNDays(n) {
  const out = [];
  for (let i = n - 1; i >= 0; i--) { const d = iso(D(i)); out.push({ d, ms: SESSIONS.filter(s => iso(new Date(s.start)) === d).reduce((a, s) => a + s.dur, 0) + (i === 0 ? S.sessionExtra : 0) }); }
  return out;
}
function barsHtml(rows, big) {
  const max = Math.max(1, ...rows.map(r => r.ms));
  const peak = rows.reduce((a, b) => b.ms > a.ms ? b : a, rows[0]);
  return '<div class="bars" style="height:' + (big ? 168 : 128) + 'px">' + rows.map(r =>
    '<div class="b' + (r === peak && r.ms ? ' peak' : '') + '" style="height:' + Math.max(2, r.ms / max * 100) + '%"><em>' + r.d.slice(5) + ' · ' + (r.ms ? durShort(r.ms) : '0') + '</em></div>').join('') + '</div>' +
    '<div class="xline"><span>' + rows[0].d.slice(5) + '</span><span>' + rows[Math.floor(rows.length / 2)].d.slice(5) + '</span><span>' + rows[rows.length - 1].d.slice(5) + '</span></div>';
}

