function pgNums(cur, pages) {
  if (pages <= 9) return Array.from({ length: pages }, (_, i) => i + 1);
  const out = [];
  for (let i = 1; i <= pages; i++) {
    if (i === 1 || i === pages || Math.abs(i - cur) <= 2) out.push(i);
    else if (out[out.length - 1] !== '…') out.push('…');
  }
  return out;
}
function pagerBarHtml(o) {
  const total = Math.max(0, Number(o.total) || 0);
  if (total <= 0) return '';
  const sizes = o.sizes || PAGE_SIZES;
  const all = Number(o.size) === 0;
  const per = all ? Math.max(1, total) : (Number(o.size) || sizes[0] || 20);
  const pages = Math.max(1, Math.ceil(total / per));
  const cur = clamp(Number(o.page) || 1, 1, pages);
  const nums = all ? [] : pgNums(cur, pages);
  const known = sizes.indexOf(Number(o.size)) >= 0;
  const custom = all || known ? '' : Number(o.size);
  const unit = o.unit || ' 条';
  return '<div class="pager-gap"></div><div class="pager-dock"><div class="pager-in" data-pages="' + pages + '">' +
    '<span class="pg-lbl">每页</span><div class="chips">' +
    sizes.map(n => '<span class="chip' + (!all && Number(o.size) === n ? ' on' : '') + '" data-pgsize="' + n + '">' + n + '</span>').join('') +
    (o.allowAll === false ? '' : '<span class="chip' + (all ? ' on' : '') + '" data-pgsize="0">全部</span>') +
    '<input class="inp" style="width:70px;text-align:center" type="number" min="1" max="' + (o.maxSize || 2000) + '" placeholder="自定义" value="' + custom + '" data-pgsize-in>' +
    '</div>' +
    '<span class="pg-sep"></span>' +
    (all
      ? '<span class="pg-info">共 ' + num(total) + unit + '</span>'
      : '<button class="btn sm" data-pg="' + (cur - 1) + '"' + (cur <= 1 ? ' disabled' : '') + '>上一页</button>' +
        nums.map(n => n === '…' ? '<span class="pg-lbl">…</span>'
          : '<button class="btn sm' + (n === cur ? ' pri' : ' ghost') + '" data-pg="' + n + '">' + n + '</button>').join('') +
        '<button class="btn sm" data-pg="' + (cur + 1) + '"' + (cur >= pages ? ' disabled' : '') + '>下一页</button>' +
        '<span class="pg-sep"></span><span class="pg-lbl">跳至</span>' +
        '<input class="inp" style="width:58px;text-align:center" type="number" min="1" max="' + pages + '" value="' + cur + '" data-pgjump>' +
        '<span class="pg-info">/ ' + pages + ' 页 · 共 ' + num(total) + unit + '</span>') +
    '</div></div>';
}
function wirePagerBar(root, h) {
  const box = root.querySelector('.pager-in');
  if (!box) return;
  const pages = Math.max(1, Number(box.getAttribute('data-pages')) || 1);
  const maxSize = h.maxSize || 2000;
  const top = () => { const v = $('#view'); if (v) v.scrollTop = 0; };
  box.querySelectorAll('[data-pg]').forEach(el => el.onclick = () => {
    h.onPage(clamp(Number(el.dataset.pg) || 1, 1, pages));
    top();
  });
  box.querySelectorAll('[data-pgsize]').forEach(el => el.onclick = () => {
    h.onSize(Number(el.dataset.pgsize));
    top();
  });
  const si = box.querySelector('[data-pgsize-in]');
  if (si) si.onchange = () => {
    const n = clamp(Number(si.value) || maxSize, 1, maxSize);
    si.value = n;
    h.onSize(n);
    top();
  };
  const ji = box.querySelector('[data-pgjump]');
  if (ji) ji.onchange = () => {
    h.onPage(clamp(Number(ji.value) || 1, 1, pages));
    top();
  };
}
