  B.pg = clamp(Number(B.pg) || 1, 1, pgMax);
  const pageList = pgAll ? list : list.slice((B.pg - 1) * pgSize, (B.pg - 1) * pgSize + pgSize);

  const CT2 = catalogTotal();
  const picked = Object.keys(sel).filter(id => series(id));
