  const pct = Math.round(r.page / total * 100);
  const pos = $('#rdPos'), pc = $('#rdPct'), scrub = $('#rdScrub'), zm = $('#rdZoom');
  if (pos) pos.textContent = r.page + ' / ' + num(total);
  if (pc) pc.textContent = pct + '%';
