    '<div class="r" style="margin-left:auto"><input class="inp" id="tocQ" style="width:104px;height:27px" placeholder="搜索 / 章号"></div></div>' +
    '<div class="rd-panel-b">' + items.join('') + '</div>';
  P.classList.add('on');
