    '<span class="ttl vttl">' + esc(m.t) + '</span>' +
    '<img src="api/lantai/v1/online/manga/' + m.mangaId + '/thumbnail" alt="" loading="lazy" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:3" onerror="lantaiThumbRetry(this)"></div>';
