  const src = S.online.browseSrc;
  const type = S.online.browseType || 'POPULAR';
  const q = (S.online.browseQ || '').trim();
  if (!src) { res.innerHTML = '<div class="empty"><h4>先选一个图源</h4></div>'; return; }
  if (type === 'SEARCH' && !q) {
    onlineResults = null; onlineKey = '';
    res.innerHTML = '<div class="empty"><svg><use href="#i-globe"/></svg><h4>输入关键词在这个源里搜索</h4></div>';
    return;
  }
  const key = 'b|' + src + '|' + type + '|' + q;
  if (!append && onlineResults && onlineKey === key) return paintOnlineResults(q);
  onlineKey = key; onlineErr = '';
  const page = append ? (onlinePage || 1) + 1 : 1;
  if (!append) {
    onlinePage = 1; onlineHasNext = false;
    res.innerHTML = '<div class="empty"><div class="spinner" style="margin:0 auto 12px"></div><h4>正在读取源站…</h4><p>首次打开某个源可能要等几秒</p></div>';
  }
