let onlineDetailCache = {}, onlineDetailBusy = false;
function onlineMangaPage(v, sourceId, mangaId) {
  loadSources();
  const id = String(mangaId);
  const cached = onlineDetailCache[id] || (onlineResults || []).find(x => String(x.mangaId) === id);
  if (!cached && !onlineDetailBusy) {
    onlineDetailBusy = true;
    LantaiRuntime.request('api/lantai/v1/online/manga/' + encodeURIComponent(id))
      .then(m => { onlineDetailCache[id] = mapOnlineList([m])[0] || { err: '源站未返回该作品' }; })
      .catch(e => { onlineDetailCache[id] = { err: onlineErrText(e) }; })
      .then(() => { onlineDetailBusy = false; if (S.route.indexOf('/online/manga/') === 0) render(); });
  }
  const m = cached && !cached.err ? cached : null;
  const err = cached && cached.err ? cached.err : '';
  const sub = (onlineSubs || []).find(x => String(x.remoteMangaId) === id);
  const srcName = (m && m.source) || sourceName(sourceId) || '在线源';
  const status = m ? (SERIES_STATUS_CN[m.status] || m.status || '状态未知') : '';
  v.innerHTML =
    '<div class="crumb"><a data-go="/online">在线源</a><i>/</i><a data-go="/online?src=' + encodeURIComponent(sourceId) + '">' + esc(srcName) + '</a><i>/</i><b>' + esc(m ? m.t : '详情') + '</b></div>' +
    (err ? '<div class="note red">' + ico('alert') + ' 读取详情失败：' + esc(err) + '</div><div class="rowflex" style="margin-top:12px"><button class="btn" data-go="/online?src=' + encodeURIComponent(sourceId) + '">' + ico('left') + '返回该源</button></div>' : '') +
    (!m && !err ? '<div class="card"><div class="empty" style="padding:44px"><div class="spinner" style="margin:0 auto 12px"></div><h4>正在读取远端详情</h4><p>元数据来自源站，首次可能需要几秒</p></div></div>' : '') +
    (m
      ? '<div class="card" style="display:flex;gap:20px;padding:20px;margin-bottom:20px;align-items:flex-start">' +
        '<div style="width:170px;flex:none">' + onlineCover(m, 170) + '</div>' +
        '<div style="flex:1;min-width:0">' +
        '<h1 style="font-family:var(--f-disp);font-size:26px;letter-spacing:1.5px">' + esc(m.t) + '</h1>' +
        '<div class="mini" style="margin:6px 0 12px">' + ([esc(m.author || ''), (m.genres || []).map(esc).join(' / ')].filter(Boolean).join(' · ') || '作者与分类未标注') + '</div>' +
        '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px">' +
        '<span class="badge moss">' + esc(srcName) + '</span>' +
        '<span class="badge ' + (m.status === 'COMPLETED' ? 'ok' : m.status === 'HIATUS' ? 'warn' : 'gold') + '">' + esc(status) + '</span>' +
        (sub ? '<span class="badge ok">已订阅</span>' : '<span class="badge">未订阅</span>') + '</div>' +
        '<div class="rowflex" style="gap:8px;flex-wrap:wrap">' +
        (sub ? '<button class="btn pri" data-go="/series/' + sub.seriesId + '">' + ico('play') + '打开系列</button>'
          : '<button class="btn pri" id="odSub">' + ico('plus') + '订阅这部</button>') +
        '<button class="btn" data-go="/online?src=' + encodeURIComponent(sourceId) + '">' + ico('left') + '返回该源</button>' +
        '</div>' +
        '<div class="grid g-2" style="gap:6px 22px;margin-top:14px">' +
        kvLine('远端 ID', String(m.mangaId)) + kvLine('图源 ID', sourceId) +
        '</div></div></div>' +
        (m.desc ? '<div class="card" style="margin-bottom:18px"><div class="card-h"><h3>' + ico('file') + ' 简介</h3></div>' +
          '<div class="note" style="white-space:pre-wrap;line-height:1.75;max-height:none">' + esc(m.desc) + '</div></div>' : '') +
        '<div class="note gold">' + ico('shield') + ' 该作品尚未进入本地书库；订阅后会按远端章节建立占位章节，之后可逐章下载存档并参与进度、书签与阅读统计。</div>'
      : '');
  wire(v);
  const sb = v.querySelector('#odSub');
  if (sb && m) sb.onclick = () => subscribe(m);
}
function subscribe(m) {
  if (!m) return;
  const known = (onlineSubs || []).find(x => x.remoteMangaId === String(m.mangaId));
  if (known) return go('/series/' + known.seriesId);
  openModal({
    title: '订阅《' + m.t + '》', width: 520,
    body: '<div style="display:flex;gap:14px;margin-bottom:14px">' + onlineCover(m, 76) +
      '<div style="flex:1;min-width:0"><div class="mini">' + esc(m.author || '作者未知') + ' · ' + esc(m.source) + '</div>' +
      '<div class="mini" style="margin-top:6px">' + esc((m.genres || []).join(' / ') || '未标注分类') + '</div>' +
      '<div class="mini" style="margin-top:6px">' + esc(SERIES_STATUS_CN[m.status] || m.status || '状态未知') + '</div></div></div>' +
      '<div class="note gold">' + ico('shield') + ' 订阅会按远端章节创建系列与占位章节，之后可逐章下载存档。</div>',
    foot: '<button class="btn" data-x>取消</button><button class="btn pri" data-ok>确认订阅</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => runSubscribe(m);
    }
  });
}
function runSubscribe(m) {
  if (!window.LantaiRuntime) return toast('后端不可用', 'err');
  const btn = $('#modal [data-ok]');
  btn.disabled = true; btn.innerHTML = '<span class="spinner" style="margin-right:6px"></span>正在创建…';
  LantaiRuntime.request('api/lantai/v1/online/subscribe', { method: 'POST', body: { sourceId: m.sourceId, mangaId: m.mangaId } })
    .then(r => {
      closeModal();
      toast(r.alreadySubscribed ? '已在订阅：' + r.title : '已订阅《' + r.title + '》，共 ' + num(r.bookCount) + ' 章', 'ok', 4000);
      return refreshOnline().then(() => { renderNav(); go('/series/' + r.seriesId); });
    })
    .catch(e => {
      btn.disabled = false; btn.textContent = '确认订阅';
      toast('订阅失败：' + onlineErrText(e), 'err', 4200);
    });
}
