function rtScript(kind) {
  LantaiRuntime.request('api/lantai/v1/runtimes/' + kind + '/script')
    .then(steps => {
      openModal({
        title: RT_META[kind].name + ' 手动安装脚本', width: 680,
        body: '<div class="mini" style="margin-bottom:10px">与管理面板走同一套步骤，可复制到容器里直接执行。</div>' +
          steps.map(s => '<div style="margin-bottom:10px"><div class="mini" style="color:var(--acc-2);margin-bottom:4px">' +
            esc(s.title) + '</div><pre class="mono" style="white-space:pre-wrap;background:var(--bg-4);padding:9px 11px;' +
            'border-radius:8px;font-size:11.5px;line-height:1.6;margin:0">' + esc(s.command) + '</pre></div>').join(''),
        foot: '<button class="btn" data-x>关闭</button><button class="btn pri" data-copy>复制全部</button>',
        after() {
          $('#modal [data-x]').onclick = closeModal;
          $('#modal [data-copy]').onclick = () => {
            const text = steps.map(s => '# ' + s.title + '\n' + s.command).join('\n\n');
            navigator.clipboard.writeText(text).then(() => toast('脚本已复制', 'ok')).catch(() => toast('复制失败，请手动选择', 'err'));
          };
        }
      });
    })
    .catch(e => toast('读取脚本失败：' + (e.message || e), 'err', 5200));
}
function wireRuntime(v) {
  v.querySelectorAll('[data-rt-refresh]').forEach(el => el.onclick = () => rtLoad());
  v.querySelectorAll('[data-rt-pull]').forEach(el => el.onclick = () => rtPull(el.dataset.rtPull, el));
  v.querySelectorAll('[data-rt-progress]').forEach(el => el.onclick = () => rtPoll(el.dataset.rtProgress));
  v.querySelectorAll('[data-rt-file]').forEach(el => el.onchange = () => rtUpload(el.dataset.rtFile, el.files[0], el));
  v.querySelectorAll('[data-rt-uninstall]').forEach(el => el.onclick = () => rtUninstall(el.dataset.rtUninstall));
  v.querySelectorAll('[data-rt-script]').forEach(el => el.onclick = () => rtScript(el.dataset.rtScript));
  v.querySelectorAll('[data-rt-enable]').forEach(el => el.onchange = () => rtEnable(el.dataset.rtEnable, el.checked));
  v.querySelectorAll('[data-cal-settings]').forEach(el => el.onclick = () => calSettingsModal());
}
function calSettingsModal() {
  if (!window.LantaiRuntime) return;
  LantaiRuntime.request('api/lantai/v1/calibre/status')
    .then(st => {
      const modes = [['on-demand', '按需转换'], ['eager', '扫描时预转'], ['never', '只留原文件']];
      let mode = st.mode || 'on-demand';
      openModal({
        title: 'Calibre 转换设置', width: 560,
        body: '<div class="field"><label>转换模式</label><div class="seg">' +
          modes.map(x => '<button class="' + (mode === x[0] ? 'on' : '') + '" data-calmode="' + x[0] + '">' + x[1] + '</button>').join('') +
          '</div><div class="mini" style="margin-top:6px">按需：首次打开受管格式时才转；预转：扫描完成后立即排队转换；只留原文件：不转换，受管格式仅提供下载。</div></div>' +
          '<div class="field"><label>ebook-convert 路径（留空用兰台托管的安装，可指到宿主机已有的 Calibre）</label>' +
          '<div class="rowflex" style="gap:6px"><input class="inp mono" id="calPath" style="flex:1;font-size:11.5px" value="' + esc(st.executablePath || '') + '" placeholder="/usr/bin/ebook-convert">' +
          '<button class="btn sm" data-calprobe>检测</button></div><div id="calProbeOut" class="mini" style="margin-top:6px"></div></div>' +
          kvLine('安装目录', st.installDir || '—') +
          kvLine('当前状态', st.available ? ('可用' + (st.version ? ' · ' + st.version : '')) : (st.message || '不可用')) +
          '<div class="note" style="margin-top:10px">容器里装失败多半是镜像缺 python3 / Qt 运行库（alpine 是 musl，官方 Calibre 是 glibc 构建）。可以上传官方 .txz 安装包，或把宿主机已装好的 ebook-convert 路径指过来。</div>',
        foot: '<button class="btn" data-x>关闭</button><button class="btn pri" data-cal-save>保存</button>',
        after() {
          const x = $('#modal [data-x]');
          if (x) x.onclick = closeModal;
          $$('#modal [data-calmode]').forEach(el => el.onclick = () => {
            mode = el.dataset.calmode;
            $$('#modal [data-calmode]').forEach(x2 => x2.classList.toggle('on', x2 === el));
          });
          const pb = $('#modal [data-calprobe]');
          if (pb) pb.onclick = () => {
            const path = ($('#calPath') || {}).value || '';
            if (!path.trim()) return toast('先填一个 ebook-convert 路径再检测', 'err');
            pb.disabled = true;
            LantaiRuntime.request('api/lantai/v1/calibre/probe', { method: 'POST', body: { path: path.trim() } })
              .then(r => { $('#calProbeOut').textContent = r.available ? ('可用 · ' + (r.version || '已检测')) : '这个路径下没有可用的 ebook-convert'; })
              .catch(e => { $('#calProbeOut').textContent = '检测失败：' + onlineErrText(e); })
              .then(() => { pb.disabled = false; });
          };
          const save = $('#modal [data-cal-save]');
          if (save) save.onclick = () => {
            const raw = (($('#calPath') || {}).value || '').trim();
            const current = st.executablePath || '';
            save.disabled = true;
            LantaiRuntime.request('api/lantai/v1/calibre/mode', { method: 'PUT', body: { mode: mode } })
              .then(() => {
                if (raw === current) return null;
                return raw
                  ? LantaiRuntime.request('api/lantai/v1/calibre/path', { method: 'PUT', body: { path: raw } })
                  : LantaiRuntime.request('api/lantai/v1/calibre/path', { method: 'DELETE' });
              })
              .then(() => { closeModal(); toast('Calibre 设置已保存', 'ok'); rtLoad(); })
              .catch(e => {
                const msg = onlineErrText(e);
                toast(/working ebook-convert/i.test(msg)
                  ? '转换模式已保存；这个路径下没有能用的 ebook-convert，路径未生效'
                  : '保存失败：' + msg, 'err', 8000);
                rtLoad();
              })
              .then(() => { save.disabled = false; });
          };
        }
      });
    })
    .catch(e => toast('读取 Calibre 状态失败：' + onlineErrText(e), 'err'));
}

