    const pages = Math.max(1, Math.ceil(g.items.length / TQ_SUB));
    const cur = Math.min(Math.max(0, taskQ.sub[g.key] || 0), pages - 1);
    const slice = g.items.slice(cur * TQ_SUB, cur * TQ_SUB + TQ_SUB);
