function wireTaskQueue(v) {
  const act = k => {
    if (!window.LantaiRuntime) return;
    if (k === 'refresh') return loadTaskQueue();
    if (k === 'clear') {
      if (!window.confirm('清空所有排队中的任务？进行中的不会中止。')) return;
      LantaiRuntime.request('api/lantai/v1/tasks/all', { method: 'DELETE' })
        .then(r => { toast('已清空 ' + ((r && r.deleted) || 0) + ' 条排队任务', 'ok'); taskQ.data = null; return reloadTasksAndQueue(); })
        .catch(e => toast('清空失败：' + onlineErrText(e), 'err'));
      return;
    }
    const url = 'api/lantai/v1/tasks/' + k;
    LantaiRuntime.request(url, { method: 'POST' })
      .then(() => { toast(k === 'pause' ? '已暂停派发新任务' : '已恢复', 'ok'); loadTaskQueue(); })
      .catch(e => toast('操作失败：' + onlineErrText(e), 'err'));
  };
  v.querySelectorAll('[data-tqact]').forEach(el => el.onclick = () => act(el.dataset.tqact));
  const poolEl = v.querySelector('[data-tqpool]');
  if (poolEl) poolEl.onchange = () => {
    const n = Math.floor(Number(poolEl.value));
    if (!(n >= 1)) { poolEl.value = sysSettings && sysSettings.taskPoolSize != null ? sysSettings.taskPoolSize : ''; return; }
    saveSysSetting({ taskPoolSize: Math.min(32, n) }).then(ok => {
      if (!ok) { poolEl.value = sysSettings && sysSettings.taskPoolSize != null ? sysSettings.taskPoolSize : ''; return; }
      if (S.route === '/tasks') render();
    });
  };
  v.querySelectorAll('[data-tqstate]').forEach(el => el.onclick = () => { taskQ.state = el.dataset.tqstate; taskQ.page = 0; taskQ.data = null; render(); });
  v.querySelectorAll('[data-tqtype]').forEach(el => el.onclick = () => { taskQ.type = el.dataset.tqtype; taskQ.page = 0; taskQ.data = null; render(); });
  const onHist = (taskQ.tab || 'queue') === 'history';
  wirePagerBar(v, {
    maxSize: 500,
    onPage: p => {
      if (onHist) { taskQ.hpage = p - 1; taskQ.hist = null; }
      else { taskQ.page = p - 1; taskQ.data = null; }
      render();
    },
    onSize: s => {
      if (onHist) { taskQ.hsize = s; taskQ.hpage = 0; taskQ.hist = null; }
      else { taskQ.size = s; taskQ.page = 0; taskQ.data = null; }
      render();
    }
  });
  v.querySelectorAll('[data-tqdel]').forEach(el => el.onclick = () => {
    LantaiRuntime.request('api/lantai/v1/tasks/' + el.dataset.tqdel, { method: 'DELETE' })
      .then(() => { toast('已取消', 'ok'); taskQ.data = null; return reloadTasksAndQueue(); })
      .catch(e => toast('取消失败：' + onlineErrText(e), 'err'));
  });
  v.querySelectorAll('[data-tqtab]').forEach(el => el.onclick = () => {
    taskQ.tab = el.dataset.tqtab;
    if (taskQ.tab === 'history') taskQ.hist = null;
    render();
  });
  v.querySelectorAll('[data-tqgroup]').forEach(el => el.onclick = () => {
    const k = el.dataset.tqgroup;
    taskQ.open[k] = !taskQ.open[k];
    render();
  });
  v.querySelectorAll('[data-tqsub]').forEach(el => el.onclick = () => {
    const k = el.dataset.tqsub;
    taskQ.sub[k] = Math.max(0, (taskQ.sub[k] || 0) + Number(el.dataset.dir));
    render();
  });
  v.querySelectorAll('[data-tqhstatus]').forEach(el => el.onclick = () => {
    taskQ.hstatus = el.dataset.tqhstatus; taskQ.hpage = 0; taskQ.hist = null; render();
  });
  v.querySelectorAll('[data-tqhtype]').forEach(el => el.onclick = () => {
    taskQ.htype = el.dataset.tqhtype; taskQ.hpage = 0; taskQ.hist = null; render();
  });
  const hc = v.querySelector('[data-tqhclear]');
  if (hc) hc.onclick = () => {
    if (!window.confirm('清空全部完成记录？')) return;
    LantaiRuntime.request('api/lantai/v1/tasks/history', { method: 'DELETE' })
      .then(r => { toast('已清空 ' + ((r && r.deleted) || 0) + ' 条记录', 'ok'); taskQ.hist = null; taskQ.hpage = 0; render(); })
      .catch(e => toast('清空失败：' + onlineErrText(e), 'err'));
  };
}
