          (dirs.length
            ? dirs.map(x => '<div class="fs-i" data-fsgo="' + esc(x.path) + '">' + ico('folder') + '<span>' + esc(x.name) + '</span></div>').join('')
            : '<div class="mini" style="padding:10px">没有子目录</div>') +
          '</div></div>';
        host.querySelector('[data-fsup]').onclick = () => { if (p) load(d.parent || ''); };
