const LOG_LV = [['', '全部'], ['ERROR', 'ERROR'], ['WARN', 'WARN'], ['INFO', 'INFO'], ['DEBUG', 'DEBUG']];
const LOG_LEVELS = ['INHERIT', 'TRACE', 'DEBUG', 'INFO', 'WARN', 'ERROR', 'OFF'];
const LOG_TAIL = 2000;
const LOGS = { files: null, file: '', entries: [], cursor: 0, hasMore: false, level: '', q: '', levels: null, busy: false, err: '', follow: false, src: null, lvOpen: false, lvQ: '', lvBusy: false, page: 0, size: 50 };
function logLvCls(l) {
  const v = (l || '').toUpperCase();
  return v === 'ERROR' || v === 'FATAL' ? 'bad' : v === 'WARN' ? 'warn' : v === 'DEBUG' || v === 'TRACE' ? '' : 'ok';
}
function logTime(t) { return String(t || '').replace('T', ' ').replace(/\.\d+/, '').replace(/(Z|[+-]\d{2}:?\d{2})$/, ''); }
function logShort(n) { const p = String(n || '').split('.'); return p.length > 2 ? p.slice(-2).join('.') : String(n || ''); }
function logRows() {
  if (!LOGS.entries.length) {
    return '<div class="empty" style="padding:26px"><svg><use href="#i-list"/></svg><h4>' + (LOGS.busy ? '正在读取日志' : '没有匹配的日志行') + '</h4>' +
      '<p>' + (LOGS.busy ? '首次加载会扫描到文件末尾，稍候。' : '换个级别或关键词，也可以切换日志文件。') + '</p></div>';
  }
  const all = LOGS.entries.slice().reverse();
  const per = LOGS.size || 50;
  const pages = Math.max(1, Math.ceil(all.length / per));
  const cur = clamp((LOGS.page || 0) + 1, 1, pages);
  const rows = all.slice((cur - 1) * per, cur * per).map(e =>
    '<tr><td class="mono mini" style="white-space:nowrap">' + esc(logTime(e.time)) + '</td>' +
    '<td><span class="badge ' + logLvCls(e.level) + '">' + esc((e.level || '—').toUpperCase()) + '</span></td>' +
    '<td class="mono mini" title="' + esc(e.loggerName) + '" style="max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(logShort(e.loggerName)) + '</td>' +
    '<td class="mono mini" style="white-space:pre-wrap;word-break:break-all">' + esc(e.message) + '</td></tr>').join('');
  return '<div class="tbl-wrap"><table class="tbl"><thead><tr><th style="width:132px">时间</th><th style="width:66px">级别</th><th style="width:180px">来源</th><th>内容</th></tr></thead><tbody>' + rows + '</tbody></table></div>' +
    pagerBarHtml({ page: cur, size: per, total: all.length, unit: ' 条', allowAll: false, sizes: TASK_PAGE_SIZES, maxSize: 500 });
}
function loadLogFiles() {
  if (!window.LantaiRuntime) return;
  LantaiRuntime.request('api/lantai/v1/logs/files')
    .then(list => {
      LOGS.files = Array.isArray(list) ? list : [];
      LOGS.err = '';
      if (!LOGS.file && LOGS.files.length) { LOGS.file = LOGS.files[0].name; loadLogEntries(true); return; }
      if (S.route.indexOf('/logs') === 0) render();
    })
    .catch(e => {
      LOGS.files = [];
      LOGS.err = '日志文件列表读取失败：' + onlineErrText(e);
      if (S.route.indexOf('/logs') === 0) render();
    });
}
function loadLogEntries(reset) {
  if (!window.LantaiRuntime || LOGS.busy) return;
  if (reset) { LOGS.entries = []; LOGS.cursor = 0; LOGS.hasMore = true; }
  LOGS.busy = true;
  if (S.route.indexOf('/logs') === 0) render();
  const qs = ['limit=2000'];
  if (LOGS.file) qs.push('file=' + encodeURIComponent(LOGS.file));
  if (LOGS.level) qs.push('level=' + encodeURIComponent(LOGS.level));
  if ((LOGS.q || '').trim()) qs.push('q=' + encodeURIComponent(LOGS.q.trim()));
  let rounds = 0;
  const step = () => {
    LantaiRuntime.request('api/lantai/v1/logs/entries?' + qs.join('&') + '&cursor=' + LOGS.cursor)
      .then(page => {
        if (!page) { LOGS.busy = false; return; }
        const list = Array.isArray(page.entries) ? page.entries : [];
        LOGS.entries = LOGS.entries.concat(list).slice(-LOG_TAIL);
        LOGS.cursor = page.nextCursor || LOGS.cursor;
        LOGS.hasMore = !!page.hasMore;
        LOGS.file = page.file || LOGS.file;
        LOGS.err = '';
        rounds++;
        if (LOGS.hasMore && rounds < 10 && list.length) return step();
        LOGS.busy = false;
        if (S.route.indexOf('/logs') === 0) render();
      })
      .catch(e => {
        LOGS.busy = false;
        LOGS.err = '日志读取失败：' + onlineErrText(e);
        if (S.route.indexOf('/logs') === 0) render();
      });
  };
  step();
}
function loadLogLevels() {
  if (!window.LantaiRuntime || LOGS.lvBusy) return;
  LOGS.lvBusy = true;
  LantaiRuntime.request('api/lantai/v1/logs/levels')
    .then(list => { LOGS.levels = Array.isArray(list) ? list : []; })
    .catch(e => { LOGS.levels = []; toast('日志级别读取失败：' + onlineErrText(e), 'err'); })
    .then(() => { LOGS.lvBusy = false; if (S.route.indexOf('/logs') === 0) render(); });
}
function logLevelRows() {
  const q = (LOGS.lvQ || '').trim().toLowerCase();
  const list = (LOGS.levels || []).filter(x => !q || x.name.toLowerCase().indexOf(q) >= 0);
  if (!list.length) return '<tr><td colspan="4"><div class="mini">没有匹配的 logger。</div></td></tr>';
  return list.map(x => '<tr><td class="mono mini">' + esc(x.name) + '</td>' +
    '<td class="mini">' + esc(x.configuredLevel || '继承') + '</td><td class="mini">' + esc(x.effectiveLevel || '—') + '</td>' +
    '<td><select class="inp" style="height:28px;font-size:11.5px" data-lvset="' + esc(x.name) + '">' +
    LOG_LEVELS.map(l => '<option value="' + l + '"' + ((x.configuredLevel || 'INHERIT') === l ? ' selected' : '') + '>' + l + '</option>').join('') +
    '</select></td></tr>').join('');
}
function wireLogLevels(root) {
  root.querySelectorAll('[data-lvset]').forEach(el => el.onchange = () => {
    const name = el.dataset.lvset, lvl = el.value, body = { levels: {} };
    body.levels[name] = lvl;
    LantaiRuntime.request('api/lantai/v1/logs/levels', { method: 'PUT', body: body })
      .then(list => { LOGS.levels = Array.isArray(list) ? list : LOGS.levels; toast(name + ' → ' + lvl, 'ok'); render(); })
      .catch(e => { toast('级别修改失败：' + onlineErrText(e), 'err'); render(); });
  });
}
function logLevelsCard() {
  if (!LOGS.lvOpen) {
    return '<div class="card" style="margin-top:16px"><div class="card-h"><h3>' + ico('settings') + ' 日志级别</h3>' +
      '<div class="r"><button class="btn sm" data-lvopen>展开</button></div></div>' +
      '<div class="mini">运行期调整 logger 级别，只影响本次运行，重启后回到配置文件里的值。</div></div>';
  }
  if (LOGS.levels === null) loadLogLevels();
  return '<div class="card" style="margin-top:16px"><div class="card-h"><h3>' + ico('settings') + ' 日志级别</h3>' +
    '<div class="r"><button class="btn sm ghost" data-lvreset>' + ico('sync') + '恢复默认</button>' +
    '<button class="btn sm" data-lvopen>收起</button></div></div>' +
    '<input class="inp" id="lvQ" style="width:260px;height:30px;margin-bottom:12px" placeholder="过滤 logger…" value="' + esc(LOGS.lvQ) + '">' +
    '<div style="max-height:360px;overflow:auto"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Logger</th><th style="width:96px">已配置</th><th style="width:96px">实际</th><th style="width:150px">调整</th></tr></thead>' +
    '<tbody id="lvBody">' + logLevelRows() + '</tbody></table></div></div></div>';
}
function logFollow(on) {
  if (LOGS.src) { LOGS.src.close(); LOGS.src = null; }
  LOGS.follow = !!on;
  if (!on || !window.LantaiRuntime) { if (S.route.indexOf('/logs') === 0) render(); return; }
  const qs = [];
  if (LOGS.file) qs.push('file=' + encodeURIComponent(LOGS.file));
  if (LOGS.level) qs.push('level=' + encodeURIComponent(LOGS.level));
  if ((LOGS.q || '').trim()) qs.push('q=' + encodeURIComponent(LOGS.q.trim()));
  const es = new EventSource(LantaiRuntime.base + 'api/lantai/v1/logs/stream' + (qs.length ? '?' + qs.join('&') : ''));
  es.addEventListener('log', ev => {
    let list = [];
    try { list = JSON.parse(ev.data); } catch (e) { return; }
    if (!Array.isArray(list) || !list.length) return;
    LOGS.entries = LOGS.entries.concat(list).slice(-LOG_TAIL);
    LOGS.page = 0;
    const box = document.querySelector('#logList');
    if (box) { box.innerHTML = logRows(); wirePagerBar(box, logPagerHandlers()); } else render();
  });
  es.onerror = () => {
    es.close(); LOGS.src = null; LOGS.follow = false;
    toast('日志跟随已断开', 'warn');
    if (S.route.indexOf('/logs') === 0) render();
  };
  LOGS.src = es;
  render();
}
function logPagerHandlers() {
  return {
    maxSize: 500,
    onPage: p => { LOGS.page = p - 1; render(); },
    onSize: s => { LOGS.size = s; LOGS.page = 0; render(); }
  };
}
const LOG_SRC = { lantai: '兰台', extensions: '功能拓展', suwayomi: 'Suwayomi' };
function logTabsHtml(tab) {
  return '<div class="tabs">' + [['run', '运行日志'], ['audit', '管理日志']].map(x =>
    '<button class="' + (tab === x[0] ? 'on' : '') + '" data-logtab="' + x[0] + '">' + x[1] + '</button>').join('') + '</div>';
}
function logPage(v, tab) {
  if (LOGS.src && tab !== 'run') { LOGS.src.close(); LOGS.src = null; LOGS.follow = false; }
  if (!window.LantaiRuntime) {
    v.innerHTML = '<div class="ph"><div><h1>日志</h1><div class="sub">需要在线实例与管理员权限</div></div></div>' +
      '<div class="note red">后端不可用，无法读取日志。</div>';
    return;
  }
  v.innerHTML = '<div class="ph"><div><h1>日志</h1><div class="sub">' +
    (tab === 'audit' ? '账户、内容与系统变更 · 保留 90 天' : '服务端日志文件 · 敏感字段自动脱敏') +
    ' · 需管理员权限</div></div></div>' + logTabsHtml(tab);
  v.querySelectorAll('[data-logtab]').forEach(el => el.onclick = () => go(el.dataset.logtab === 'audit' ? '/logs/audit' : '/logs'));
  if (tab === 'audit') mountLogAudit(v); else mountLogRun(v);
}
function mountLogRun(v) {
  if (LOGS.files === null) loadLogFiles();
  const cur = (LOGS.files || []).find(x => x.name === LOGS.file);
  v.insertAdjacentHTML('beforeend', '<div class="rowflex" style="margin-bottom:14px;gap:8px;flex-wrap:wrap">' +
    '<button class="btn" data-logrefresh>' + ico('sync') + '刷新</button>' +
    '<button class="btn' + (LOGS.follow ? ' pri' : '') + '" data-logfollow>' + ico(LOGS.follow ? 'close' : 'play') + (LOGS.follow ? '停止跟随' : '实时跟随') + '</button>' +
    '<button class="btn" data-logdl>' + ico('dl') + '下载</button></div>' +
    (LOGS.err ? '<div class="note red" style="margin-bottom:14px">' + esc(LOGS.err) + '</div>' : '') +
    '<div class="card" style="margin-bottom:16px"><div class="rowflex" style="gap:10px;flex-wrap:wrap">' +
    '<select class="inp" id="logFile" style="width:300px;height:31px">' +
    ((LOGS.files || []).length
      ? LOGS.files.map(x => '<option value="' + esc(x.name) + '"' + (x.name === LOGS.file ? ' selected' : '') + '>' +
        (LOG_SRC[x.source] && x.source !== 'lantai' ? '[' + LOG_SRC[x.source] + '] ' : '') + esc(x.name) + ' · ' + bytes(x.sizeBytes) + (x.current ? ' · 当前' : '') + '</option>').join('')
      : '<option value="">没有日志文件</option>') + '</select>' +
    '<div class="seg">' + LOG_LV.map(x => '<button class="' + (LOGS.level === x[0] ? 'on' : '') + '" data-loglv="' + x[0] + '">' + x[1] + '</button>').join('') + '</div>' +
    '<input class="inp" id="logQ" style="width:220px;height:31px;margin-left:auto" placeholder="搜索关键词…" value="' + esc(LOGS.q) + '">' +
    '</div>' + (cur ? '<div class="mini" style="margin-top:11px">最近写入 ' + esc(String(cur.lastModified || '').replace('T', ' ').slice(0, 19)) + ' · ' + (cur.compressed ? '已归档压缩' : '纯文本') + ' · 来源 ' + esc(LOG_SRC[cur.source] || cur.source || '兰台') +
      (cur.source === 'suwayomi' ? '（Suwayomi 自身日志，时间只有时分秒，不支持日期范围筛选）' : '') + '</div>' : '') + '</div>' +
    '<div class="card"><div class="card-h"><h3>' + ico('list') + ' 日志条目</h3>' +
    '<div class="r"><span class="mini">' + (LOGS.busy ? '读取中…' : '最近 ' + LOGS.entries.length + ' 条') + '</span></div></div>' +
    '<div id="logList">' + logRows() + '</div></div>' +
    logLevelsCard());
  wire(v);
  const sel = v.querySelector('#logFile');
  if (sel) sel.onchange = () => { LOGS.file = sel.value; loadLogEntries(true); };
  v.querySelectorAll('[data-loglv]').forEach(el => el.onclick = () => { LOGS.level = el.dataset.loglv; loadLogEntries(true); });
  const q = v.querySelector('#logQ');
  if (q) {
    let t = null;
    q.oninput = () => { LOGS.q = q.value; clearTimeout(t); t = setTimeout(() => loadLogEntries(true), 400); };
  }
  const rf = v.querySelector('[data-logrefresh]');
  if (rf) rf.onclick = () => { toast('正在读取最新日志'); loadLogFiles(); };
  const fl = v.querySelector('[data-logfollow]');
  if (fl) fl.onclick = () => logFollow(!LOGS.follow);
  const dl = v.querySelector('[data-logdl]');
  if (dl) dl.onclick = () => {
    if (!LOGS.file) return toast('没有可下载的文件', 'err');
    window.open(LantaiRuntime.base + 'api/lantai/v1/logs/files/' + encodeURIComponent(LOGS.file) + '/download', '_blank');
  };
  v.querySelectorAll('[data-lvopen]').forEach(el => el.onclick = () => {
    LOGS.lvOpen = !LOGS.lvOpen;
    if (LOGS.lvOpen && LOGS.levels === null) loadLogLevels();
    render();
  });
  const lq = v.querySelector('#lvQ');
  if (lq) lq.oninput = () => {
    LOGS.lvQ = lq.value;
    const tb = v.querySelector('#lvBody');
    if (tb) { tb.innerHTML = logLevelRows(); wireLogLevels(tb); }
  };
  wireLogLevels(v);
  const rs = v.querySelector('[data-lvreset]');
  if (rs) rs.onclick = () => {
    const names = (LOGS.levels || []).filter(x => x.configuredLevel).map(x => x.name);
    if (!names.length) return toast('没有已修改的级别');
    LantaiRuntime.request('api/lantai/v1/logs/levels', { method: 'DELETE', body: { names: names } })
      .then(list => { LOGS.levels = Array.isArray(list) ? list : LOGS.levels; toast('已恢复到默认级别', 'ok'); render(); })
      .catch(e => toast('恢复失败：' + onlineErrText(e), 'err'));
  };
  wirePagerBar(v, logPagerHandlers());
}
